    50→    /**
    51→     * Salva (cria ou atualiza) um cargo e todas as suas relações N:M.
    52→     * (Criado no Passo 11 - Usado por cargos_form.php)
    53→     *
    54→     * @param array $postData Os dados vindo diretamente do $_POST.
    55→     * @return int O ID do cargo salvo.
    56→     * @throws Exception Se a validação falhar ou o salvamento falhar.
    57→     */
    58→    public function save(array $postData): int
    59→    {
    60→        $cargoIdSubmissao = (int)($postData['cargoId'] ?? 0);
    61→        $isUpdating = $cargoIdSubmissao > 0;
    62→
    63→        // --- 6. VERIFICAÇÃO DE PERMISSÃO (AuthService) ---
    64→        $permissionNeeded = $isUpdating ? 'cargos:edit' : 'cargos:create';
    65→        // Lança uma exceção se o usuário não tiver permissão
    66→        $this->authService->checkAndFail($permissionNeeded); 
    67→
    68→        // 1. Captura dos Dados Principais
    69→        $data = [
    70→            'cargoNome' => trim($postData['cargoNome'] ?? ''),
    71→            'cargoDescricao' => trim($postData['cargoDescricao'] ?? null),
    72→            'cboId' => trim($postData['cboId'] ?? 0),
    73→            'cargoResumo' => trim($postData['cargoResumo'] ?? null),
    74→            'escolaridadeId' => (int)($postData['escolaridadeId'] ?? 0),
    75→            'cargoExperiencia' => trim($postData['cargoExperiencia'] ?? null),
    76→            'cargoCondicoes' => trim($postData['cargoCondicoes'] ?? null),
    77→            'cargoComplexidade' => trim($postData['cargoComplexidade'] ?? null),
    78→            'cargoResponsabilidades' => trim($postData['cargoResponsabilidades'] ?? null),
    79→            'faixaId' => empty($postData['faixaId']) ? null : (int)$postData['faixaId'],
    80→            'nivelHierarquicoId' => empty($postData['nivelHierarquicoId']) ? null : (int)$postData['nivelHierarquicoId'],
    81→            'cargoSupervisorId' => empty($postData['cargoSupervisorId']) ? null : (int)$postData['cargoSupervisorId'],
    82→        ];
    83→
    84→        // 2. Validação
    85→        if (empty($data['cargoNome']) || empty($data['cboId']) || $data['escolaridadeId'] <= 0) {
    86→            throw new Exception("Os campos Nome do Cargo, CBO e Escolaridade são obrigatórios.");
    87→        }
    88→
    89→        // 3. Captura dos Dados de Relacionamento
    90→        $relacionamentosSimples = [
    91→            'cargos_area' => ['coluna' => 'areaId', 'valores' => (array)($postData['areaId'] ?? [])],
    92→            'habilidades_cargo' => ['coluna' => 'habilidadeId', 'valores' => (array)($postData['habilidadeId'] ?? [])],
    93→            'caracteristicas_cargo' => ['coluna' => 'caracteristicaId', 'valores' => (array)($postData['caracteristicaId'] ?? [])],
    94→            'recursos_grupos_cargo' => ['coluna' => 'recursoGrupoId', 'valores' => (array)($postData['recursoGrupoId'] ?? [])],
    95→        ];
    96→
    97→        $riscosInput = [
    98→            'riscoId' => (array)($postData['riscoId'] ?? []),
    99→            'riscoDescricao' => (array)($postData['riscoDescricao'] ?? []),
   100→        ];
   101→
   102→        $cursosInput = [
   103→            'cursoId' => (array)($postData['cursoId'] ?? []),
   104→            'cursoCargoObrigatorio' => (array)($postData['cursoCargoObrigatorio'] ?? []),
   105→            'cursoCargoObs' => (array)($postData['cursoCargoObs'] ?? []),
   106→        ];
   107→
   108→        $sinonimosInput = (array)($postData['sinonimoNome'] ?? []);
   109→
   110→        // 4. Inicia a Transação
   111→        $this->pdo->beginTransaction();
   112→        try {
   113→            // 5. Salva o Cargo Principal (UPDATE ou CREATE)
   114→            $fields = array_keys($data);
   115→            $bindings = array_values($data);
   116→
   117→            if ($isUpdating) {
   118→                $sql_fields = implode(' = ?, ', $fields) . ' = ?';
   119→                $sql = "UPDATE cargos SET {$sql_fields}, cargoDataAtualizacao = CURRENT_TIMESTAMP() WHERE cargoId = ?";
   120→                $bindings[] = $cargoIdSubmissao;
   121→                $stmt = $this->pdo->prepare($sql);
   122→                $stmt->execute($bindings);
   123→                $novoCargoId = $cargoIdSubmissao;
   124→
   125→                // --- 7. LOG DE AUDITORIA (UPDATE) ---
   126→                $this->auditService->log('UPDATE', 'cargos', $novoCargoId, $postData);
   127→
   128→            } else {
   129→                $sql_fields = implode(', ', $fields);
   130→                $placeholders = implode(', ', array_fill(0, count($fields), '?'));
   131→                $sql = "INSERT INTO cargos ({$sql_fields}) VALUES ({$placeholders})";
   132→                $stmt = $this->pdo->prepare($sql);
   133→                $stmt->execute($bindings);
   134→                $novoCargoId = $this->pdo->lastInsertId();
   135→                
   136→                // --- 8. LOG DE AUDITORIA (CREATE) ---
   137→                $this->auditService->log('CREATE', 'cargos', $novoCargoId, $postData);
   138→            }
   139→
   140→            // 6. Salva Relacionamentos N:M Simples
   141→            foreach ($relacionamentosSimples as $tableName => $rel) {
   142→                $column = $rel['coluna'];
   143→                $valores = $rel['valores'];
   144→                $this->pdo->prepare("DELETE FROM {$tableName} WHERE cargoId = ?")->execute([$novoCargoId]);
   145→                if (!empty($valores)) {
   146→                    $insert_sql = "INSERT INTO {$tableName} (cargoId, {$column}) VALUES (?, ?)";
   147→                    $stmt_rel = $this->pdo->prepare($insert_sql);
   148→                    foreach ($valores as $valorId) {
   149→                        $stmt_rel->execute([$novoCargoId, $valorId]);
   150→                    }
   151→                }
   152→            }
   153→
   154→            // 7. Salva Riscos (Complexo)
   155→            $this->pdo->prepare("DELETE FROM riscos_cargo WHERE cargoId = ?")->execute([$novoCargoId]);
   156→            if (!empty($riscosInput['riscoId'])) {
   157→                $sql_risco = "INSERT INTO riscos_cargo (cargoId, riscoId, riscoDescricao) VALUES (?, ?, ?)";
   158→                $stmt_risco = $this->pdo->prepare($sql_risco);
   159→                for ($i = 0; $i < count($riscosInput['riscoId']); $i++) {
   160→                    $stmt_risco->execute([$novoCargoId, (int)$riscosInput['riscoId'][$i], $riscosInput['riscoDescricao'][$i] ?? '']);
   161→                }
   162→            }
   163→
   164→            // 8. Salva Cursos (Complexo)
   165→            $this->pdo->prepare("DELETE FROM cursos_cargo WHERE cargoId = ?")->execute([$novoCargoId]);
   166→            if (!empty($cursosInput['cursoId'])) {
   167→                $sql_curso = "INSERT INTO cursos_cargo (cargoId, cursoId, cursoCargoObrigatorio, cursoCargoObs) VALUES (?, ?, ?, ?)";
   168→                $stmt_curso = $this->pdo->prepare($sql_curso);
   169→                for ($i = 0; $i < count($cursosInput['cursoId']); $i++) {
   170→                    $obrigatorio = (int)($cursosInput['cursoCargoObrigatorio'][$i] ?? 0);
   171→                    $obs = $cursosInput['cursoCargoObs'][$i] ?? '';
   172→                    $stmt_curso->execute([$novoCargoId, (int)$cursosInput['cursoId'][$i], $obrigatorio, $obs]);
   173→                }
   174→            }
   175→
   176→            // 9. Salva Sinônimos
   177→            $this->pdo->prepare("DELETE FROM cargo_sinonimos WHERE cargoId = ?")->execute([$novoCargoId]);
   178→            if (!empty($sinonimosInput)) {
   179→                $sql_sin = "INSERT INTO cargo_sinonimos (cargoId, cargoSinonimoNome) VALUES (?, ?)";
   180→                $stmt_sin = $this->pdo->prepare($sql_sin);
   181→                foreach ($sinonimosInput as $sinonimoNome) {
   182→                    $stmt_sin->execute([$novoCargoId, trim($sinonimoNome)]);
   183→                }
   184→            }
   185→
   186→            // 10. Commita a Transação
   187→            $this->pdo->commit();
   188→            return $novoCargoId;
   189→
   190→        } catch (Exception $e) {
   191→            $this->pdo->rollBack();
   192→            
   193→            // REPARO DE SEGURANÇA: Loga o erro detalhado e propaga uma exceção com mensagem genérica.
   194→            error_log('Falha fatal ao salvar Cargo: ' . $e->getMessage());
   195→            
   196→            // Propaga a exceção para a View (Controller) tratar, mas com uma mensagem segura.
   197→            throw new Exception("Erro fatal ao salvar o Cargo no banco. Tente novamente ou contate o suporte.");
   198→        }
   199→    }
