   281→    /**
   282→     * Busca cargos de forma paginada, com filtro e ordenação.
   283→     * (Criado no Passo 7 - Usado por cargos.php)
   284→     *
   285→     * @param array $params Parâmetros de busca (term, page, limit, order_by, sort_dir)
   286→     * @return array Contendo ['data', 'total', 'totalPages', 'currentPage']
   287→     */
   288→    public function findAllPaginated(array $params = []): array
   289→    {
   290→        // 1. Configuração da Paginação e Filtros
   291→        $itemsPerPage = (int)($params['limit'] ?? 10);
   292→        $currentPage = (int)($params['page'] ?? 1);
   293→        $currentPage = max(1, $currentPage); 
   294→        
   295→        $term = $params['term'] ?? '';
   296→        $sqlTerm = "%{$term}%";
   297→        
   298→        $all_bindings = [];
   299→
   300→        // 2. Query para Contagem Total
   301→        $count_sql = "
   302→            SELECT COUNT(c.cargoId)
   303→            FROM cargos c
   304→            LEFT JOIN cbos b ON b.cboId = c.cboId
   305→        ";
   306→        $count_bindings = [];
   307→
   308→        if (!empty($term)) {
   309→            $count_sql .= " WHERE c.cargoNome LIKE :term1 OR c.cargoResumo LIKE :term2 OR b.cboTituloOficial LIKE :term3";
   310→            $count_bindings[':term1'] = $sqlTerm;
   311→            $count_bindings[':term2'] = $sqlTerm;
   312→            $count_bindings[':term3'] = $sqlTerm;
   313→        }
   314→
   315→        try {
   316→            $count_stmt = $this->pdo->prepare($count_sql);
   317→            $count_stmt->execute($count_bindings);
   318→            $totalRecords = (int)$count_stmt->fetchColumn();
   319→        } catch (\PDOException $e) {
   320→            error_log("Erro ao contar cargos: " . $e->getMessage());
   321→            $totalRecords = 0;
   322→        }
   323→
   324→        // 3. Ajuste de Página
   325→        $totalPages = $totalRecords > 0 ? ceil($totalRecords / $itemsPerPage) : 1;
   326→        if ($currentPage > $totalPages) {
   327→            $currentPage = $totalPages;
   328→        }
   329→        $offset = ($currentPage - 1) * $itemsPerPage;
   330→
   331→        // 4. Query Principal
   332→        $sql = "
   333→            SELECT 
   334→                c.cargoId, c.cargoNome, c.cargoResumo, c.cargoDataAtualizacao,
   335→                b.cboTituloOficial
   336→            FROM cargos c
   337→            LEFT JOIN cbos b ON b.cboId = c.cboId
   338→        ";
   339→
   340→        if (!empty($term)) {
   341→            $sql .= " WHERE c.cargoNome LIKE :term1 OR c.cargoResumo LIKE :term2 OR b.cboTituloOficial LIKE :term3";
   342→            $all_bindings[':term1'] = $sqlTerm;
   343→            $all_bindings[':term2'] = $sqlTerm;
   344→            $all_bindings[':term3'] = $sqlTerm;
   345→        }
   346→
   347→        // 5. Validação de Colunas de Ordenação
   348→        $orderBy = $params['order_by'] ?? 'c.cargoId';
   349→        $sortDir = $params['sort_dir'] ?? 'ASC';
   350→        
   351→        $validColumns = ['c.cargoId', 'c.cargoNome', 'b.cboTituloOficial', 'c.cargoDataAtualizacao'];
   352→        $orderBy = in_array($orderBy, $validColumns) ? $orderBy : 'c.cargoId';
   353→        $sortDir = in_array(strtoupper($sortDir), ['ASC', 'DESC']) ? strtoupper($sortDir) : 'ASC';
   354→
   355→        $sql .= " ORDER BY {$orderBy} {$sortDir}";
   356→        $sql .= " LIMIT :limit OFFSET :offset";
   357→
   358→        $all_bindings[':limit'] = $itemsPerPage;
   359→        $all_bindings[':offset'] = $offset;
   360→
   361→        // 6. Executa a query principal
   362→        try {
   363→            $stmt = $this->pdo->prepare($sql);
   364→            
   365→            $stmt->bindParam(':limit', $all_bindings[':limit'], PDO::PARAM_INT);
   366→            $stmt->bindParam(':offset', $all_bindings[':offset'], PDO::PARAM_INT);
   367→            if (!empty($term)) {
   368→                $stmt->bindParam(':term1', $all_bindings[':term1']);
   369→                $stmt->bindParam(':term2', $all_bindings[':term2']);
   370→                $stmt->bindParam(':term3', $all_bindings[':term3']);
   371→            }
   372→            
   373→            $stmt->execute();
   374→            $registros = $stmt->fetchAll(PDO::FETCH_ASSOC); // Modificado para FETCH_ASSOC
   375→        } catch (\PDOException $e) {
   376→            error_log("Erro ao buscar cargos: " . $e->getMessage() . " SQL: " . $sql);
   377→            $registros = [];
   378→        }
   379→
   380→        // 7. Retorna o pacote completo
   381→        return [
   382→            'data' => $registros,
   383→            'total' => $totalRecords,
   384→            'totalPages' => $totalPages,
   385→            'currentPage' => $currentPage
   386→        ];
   387→    }
