   390→    /**
   391→     * Remove todas as referências de um Cargo em suas tabelas de junção N:M.
   392→     * (Criado no Passo 5 - Usado por delete() e save())
   393→     *
   394→     * @param int $cargoId O ID do cargo.
   395→     * @return bool True se a limpeza for bem-sucedida.
   396→     */
   397→    public function clearRelationships(int $cargoId): bool
   398→    {
   399→        $joinTables = [
   400→            'habilidades_cargo', 'caracteristicas_cargo', 'riscos_cargo',
   401→            'cargo_sinonimos', 'cursos_cargo', 'recursos_grupos_cargo',
   402→            'cargos_area'
   403→        ];
   404→        $success = true;
   405→
   406→        foreach ($joinTables as $table) {
   407→            try {
   408→                $stmt = $this->pdo->prepare("DELETE FROM {$table} WHERE cargoId = ?");
   409→                $stmt->execute([$cargoId]);
   410→            } catch (\PDOException $e) {
   411→                error_log("Falha ao limpar relacionamento N:M na tabela {$table} para Cargo ID {$cargoId}: " . $e->getMessage());
   412→                $success = false;
   413→            }
   414→        }
   415→        return $success;
   416→    }
