   418→    /**
   419→     * Exclui um cargo e todas as suas relações.
   420→     * (Criado no Passo 5 - Usado por cargos.php)
   421→     *
   422→     * @param int $id O ID do cargo a ser excluído.
   423→     * @return int O número de linhas afetadas (0 ou 1).
   424→     * @throws \Exception Se a limpeza das relações falhar.
   425→     */
   426→    public function delete(int $id): int
   427→    {
   428→        // --- 9. VERIFICAÇÃO DE PERMISSÃO (AuthService) ---
   429→        $this->authService->checkAndFail('cargos:delete');
   430→        
   431→        $this->pdo->beginTransaction();
   432→        try {
   433→            // 1. Limpa todas as referências
   434→            $cleaned = $this->clearRelationships($id);
   435→
   436→            if (!$cleaned) {
   437→                throw new \Exception("Falha ao limpar relacionamentos N:M para o Cargo ID {$id}.");
   438→            }
   439→
   440→            // 2. Exclui o cargo principal
   441→            $stmt = $this->pdo->prepare("DELETE FROM cargos WHERE cargoId = ?");
   442→            $stmt->execute([$id]);
   443→            $rowCount = $stmt->rowCount();
   444→            
   445→            // --- 10. LOG DE AUDITORIA (DELETE) ---
   446→            if ($rowCount > 0) {
   447→                $this->auditService->log('DELETE', 'cargos', $id, ['deletedCargoId' => $id]);
   448→            }
   449→
   450→            $this->pdo->commit();
   451→            return $rowCount;
   452→
   453→        } catch (\Exception $e) {
   454→            $this->pdo->rollBack();
   455→            // Propaga a exceção para que o controller possa tratá-la
   456→            throw $e;
   457→        }
   458→    }
