   460→    /**
   461→     * Carrega todos os dados de um cargo para relatórios.
   462→     * (Criado no Passo 4 - Usado por gerador_pdf.php e cargo_individual.php)
   463→     *
   464→     * @param int $cargoId O ID do cargo.
   465→     * @return array|null Os dados completos do cargo ou null se não encontrado.
   466→     */
   467→    public function findReportData(int $cargoId): ?array
   468→    {
   469→        if ($cargoId <= 0) return null;
   470→
   471→        $data = [];
   472→
   473→        try {
   474→            // 1. DADOS BÁSICOS
