   157→        $itemsPerPage = (int)($params['limit'] ?? 15);
   158→        $currentPage = (int)($params['page'] ?? 1);
   159→        $currentPage = max(1, $currentPage); 
   160→        $term = $params['term'] ?? '';
   161→        $sqlTerm = "%{$term}%";
   162→        
   163→        $where = [];
   164→        $bindings = [];
   165→
   166→        // 2. Montagem dos Filtros
   167→        if (!empty($term)) {
   168→            $where[] = "(tipoNome LIKE :term OR tipoDescricao LIKE :term)";
   169→            $bindings[':term'] = $sqlTerm;
   170→        }
   171→        
   172→        $sqlWhere = "";
   173→        if (!empty($where)) {
   174→            $sqlWhere = " WHERE " . implode(" AND ", $where);
   175→        }
   176→
   177→        // 3. Query para Contagem Total
   178→        $count_sql = "SELECT COUNT(*) FROM tipo_hierarquia" . $sqlWhere;
   179→        
   180→        try {
   181→            $count_stmt = $this->pdo->prepare($count_sql);
   182→            $count_stmt->execute($bindings);
   183→            $totalRecords = (int)$count_stmt->fetchColumn();
   184→        } catch (\PDOException $e) {
   185→            error_log("Erro ao contar tipos de hierarquia: " . $e->getMessage());
   186→            $totalRecords = 0;
   187→        }
   188→
   189→        // 4. Ajuste de Página
   190→        $totalPages = $totalRecords > 0 ? ceil($totalRecords / $itemsPerPage) : 1;
   191→        if ($currentPage > $totalPages) {
   192→            $currentPage = $totalPages;
   193→        }
   194→        $offset = ($currentPage - 1) * $itemsPerPage;
   195→
   196→        // 5. Query Principal
