        $sortDir = in_array(strtoupper($sortDir), ['ASC', 'DESC']) ? strtoupper($sortDir) : 'ASC';
        $quotedOrderFL = \App\Core\Database::quoteIdent($orderBy);

        // 2. Parâmetros de Filtro
        $sqlTerm = "%{$term}%";
        $bindings = [];

        $whereClause = "";
