echo "1. Permissão cbos:manage:\n";
$p = $pdo->query("SELECT p.\"permissionName\", rp.\"roleId\" FROM permissions p LEFT JOIN role_permissions rp ON rp.\"permissionId\"=p.\"permissionId\" AND rp.\"roleId\"=1 WHERE p.\"permissionName\"='cbos:manage'")->fetch(PDO::FETCH_ASSOC);
echo "   permissão: {$p['permissionName']} | Admin tem: " . ($p['roleId'] ? 'SIM' : 'NÃO') . "\n";

echo "\n2. Experiência - mapeamento dos 5 primeiros cargos:\n";
$cargos = $pdo->query('SELECT "cargoId","cargoNome","cargoExperiencia" FROM cargos WHERE "cargoExperiencia" IS NOT NULL LIMIT 6')->fetchAll(PDO::FETCH_ASSOC);
$expOpcoes = ['','Sem experiência','Até 3 meses','3 a 6 meses','6 meses a 1 ano','1 a 2 anos','2 a 3 anos','3 a 5 anos','Acima de 5 anos'];
foreach($cargos as $c) {
    $exp = $c['cargoExperiencia'];
    if (preg_match('/sem\s+exig|sem\s+exp/i', $exp)) $mapped = 'Sem experiência';
    elseif (preg_match('/acima.*5|mais.*5\s*an/i', $exp)) $mapped = 'Acima de 5 anos';
    elseif (preg_match('/3\s*a\s*5/i', $exp)) $mapped = '3 a 5 anos';
    elseif (preg_match('/2\s*a\s*3|30\s*mes/i', $exp)) $mapped = '2 a 3 anos';
    elseif (preg_match('/1\s*a\s*2|18\s*mes/i', $exp)) $mapped = '1 a 2 anos';
    elseif (preg_match('/1\s*(ano|an|year)|12\s*mes/i', $exp)) $mapped = '6 meses a 1 ano';
    elseif (preg_match('/6\s*mes.*1\s*an|ate.*1\s*an/i', $exp)) $mapped = '6 meses a 1 ano';
    elseif (preg_match('/6\s*(mes|month)/i', $exp)) $mapped = '6 meses a 1 ano';
    elseif (preg_match('/3\s*a\s*6|ate\s*6\s*mes/i', $exp)) $mapped = '3 a 6 meses';
    elseif (preg_match('/ate\s*3\s*mes|3\s*mes|90\s*dias/i', $exp)) $mapped = 'Até 3 meses';
    elseif (in_array($exp, $expOpcoes)) $mapped = $exp;
    else $mapped = '__custom__';
    $status = $mapped === '__custom__' ? '⚠️ custom' : '✅';
    echo "   [{$c['cargoId']}] " . substr($exp,0,30) . " → $mapped $status\n";
}

echo "\n3. Áreas - redirect após POST: corrigido\n";
echo "4. Riscos - truncamento 50 chars: removido, exibe texto completo\n";
echo "5. Select2 hierarquia - re-trigger on tab show: adicionado\n";
echo "6. Motivo de alteração: campo adicionado ao formulário + salvo no log\n";
EOF

