   338→        .text(d => d.data.level);
   339→
   340→    // Tooltip on hover
   341→    node.append('title')
   342→        .text(d => `${d.data.name}\n${d.data.level}\nClique para editar`);
   343→
   344→    // Center view
   345→    const allX = visibleNodes.map(d => d.y);
   346→    const allY = visibleNodes.map(d => d.x);
   347→    const minX = d3.min(allX) - nodeW/2 - 20;
   348→    const maxX = d3.max(allX) + nodeW/2 + 20;
   349→    const minY = d3.min(allY) - nodeH/2 - 20;
   350→    const maxY = d3.max(allY) + nodeH/2 + 20;
   351→    const treeW = maxX - minX;
   352→    const treeH = maxY - minY;
   353→    const scale = Math.min(W / treeW, H / treeH, 1.2) * 0.9;
   354→    const tx = (W - treeW * scale) / 2 - minX * scale;
   355→    const ty = (H - treeH * scale) / 2 - minY * scale;
   356→    svg.call(zoom.transform, d3.zoomIdentity.translate(tx, ty).scale(scale));
   357→
   358→    // Controls
   359→    const controlDiv = document.createElement('div');
   360→    controlDiv.style.cssText = 'position:absolute;top:12px;right:12px;display:flex;gap:6px;';
   361→    controlDiv.innerHTML = `
   362→        <button onclick="fitView()" class="btn btn-sm btn-light border" title="Centralizar"><i class="fas fa-expand-arrows-alt"></i></button>
   363→        <button onclick="zoomIn()" class="btn btn-sm btn-light border" title="Zoom +"><i class="fas fa-search-plus"></i></button>
   364→        <button onclick="zoomOut()" class="btn btn-sm btn-light border" title="Zoom -"><i class="fas fa-search-minus"></i></button>
   365→    `;
   366→    container.appendChild(controlDiv);
   367→
   368→    window.fitView = () => svg.transition().duration(500).call(zoom.transform, d3.zoomIdentity.translate(tx, ty).scale(scale));
   369→    window.zoomIn = () => svg.transition().duration(300).call(zoom.scaleBy, 1.4);
   370→    window.zoomOut = () => svg.transition().duration(300).call(zoom.scaleBy, 0.7);
   371→})();
   372→</script>
   373→<?php endif; ?>
